//! Morphological transformation engine.
//! Applies affixation, reduplication and root-and-pattern templates to root
//! words generated by the phonology engine.

use crate::archetypes::{Morphology, MorphRule};
use crate::sound_change::{is_tone_mark, is_vowel};
use rand::seq::SliceRandom;

pub struct MorphologyEngine {
    morphology: Morphology,
}

impl MorphologyEngine {
    pub fn new(morphology: Morphology) -> Self {
        Self { morphology }
    }

    /// Apply all morphology rules in order to a root word.
    /// Returns the transformed word and an optional randomly-assigned noun class.
    pub fn apply_rules(&self, root: &str) -> (String, Option<String>) {
        let mut word = root.to_string();
        for rule in &self.morphology.rules {
            match rule {
                MorphRule::Suffix(s) => word.push_str(s),
                MorphRule::Prefix(p) => word = format!("{}{}", p, word),
                MorphRule::Infix(i) => word = insert_infix(&word, i),
                MorphRule::Reduplication => word = format!("{}-{}", word, word),
                MorphRule::Template(t) => word = apply_template(t, &word),
            }
        }
        let noun_class = if let Some(classes) = &self.morphology.noun_classes {
            let mut rng = rand::thread_rng();
            classes.choose(&mut rng).cloned()
        } else {
            None
        };
        (word, noun_class)
    }
}

/// Split a word into consonant units: each maximal run of non-vowel letters is one
/// unit, so digraphs (`sh`, `kw`) and clusters stay whole. Tone superscripts and
/// hyphens are ignored.
fn consonant_units(word: &str) -> Vec<String> {
    let mut units = Vec::new();
    let mut current = String::new();
    for c in word.chars() {
        if is_ignored(c) {
            continue;
        }
        if is_vowel(c) {
            if !current.is_empty() {
                units.push(std::mem::take(&mut current));
            }
        } else {
            current.push(c);
        }
    }
    if !current.is_empty() {
        units.push(current);
    }
    units
}

fn is_ignored(c: char) -> bool {
    c == '-' || is_tone_mark(c)
}

/// Insert an infix at the segment midpoint. The infix goes before the segment at
/// that point, so tone marks stay attached to the syllable they belong to.
fn insert_infix(word: &str, infix: &str) -> String {
    let chars: Vec<char> = word.chars().collect();
    let segment_positions: Vec<usize> = (0..chars.len()).filter(|&k| !is_tone_mark(chars[k])).collect();
    let at = segment_positions.get(segment_positions.len() / 2).copied().unwrap_or(chars.len());
    let head: String = chars[..at].iter().collect();
    let tail: String = chars[at..].iter().collect();
    format!("{}{}{}", head, infix, tail)
}

/// Interleave the root's consonant units with a vocalic pattern. `C` in the
/// template takes the next unit (cycling when the root runs out); all other
/// characters are inserted literally. A root with no consonants is returned unchanged.
fn apply_template(template: &str, root: &str) -> String {
    let units = consonant_units(root);
    if units.is_empty() {
        return root.to_string();
    }
    let mut out = String::new();
    let mut next = 0usize;
    for c in template.chars() {
        if c == 'C' {
            out.push_str(&units[next % units.len()]);
            next += 1;
        } else {
            out.push(c);
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::archetypes::{Morphology, MorphRule};

    fn engine(rules: Vec<MorphRule>) -> MorphologyEngine {
        MorphologyEngine::new(Morphology { rules, noun_classes: None })
    }

    #[test]
    fn test_morphology_rules() {
        let morph = Morphology {
            rules: vec![MorphRule::Suffix("-en".to_string())],
            noun_classes: None,
        };
        let engine = MorphologyEngine::new(morph);
        let (word, noun_class) = engine.apply_rules("root");
        assert_eq!(word, "root-en");
        assert_eq!(noun_class, None);
    }

    #[test]
    fn test_infix_is_safe_on_multibyte_text() {
        // Byte midpoint of "öäö" falls inside a multi-byte character; this must not panic.
        let (word, _) = engine(vec![MorphRule::Infix("-k-".into())]).apply_rules("öäö");
        assert_eq!(word, "ö-k-äö");
    }

    #[test]
    fn test_infix_does_not_detach_tone_marks() {
        // Six segments g o n y z i put the midpoint on "y". The infix goes before it,
        // so the tone mark after "y" stays attached to "y" rather than being split off.
        let (word, _) = engine(vec![MorphRule::Infix("-k-".into())]).apply_rules("gony¹zi¹");
        assert_eq!(word, "gon-k-y¹zi¹");
    }

    #[test]
    fn test_template_interleaves_root_consonants() {
        // root "katu" has consonant units k, t; template CaCaC cycles to k, t, k
        let (word, _) = engine(vec![MorphRule::Template("CaCaC".into())]).apply_rules("katu");
        assert_eq!(word, "katak");
    }

    #[test]
    fn test_template_keeps_digraph_units_whole() {
        let (word, _) = engine(vec![MorphRule::Template("CiC".into())]).apply_rules("shaku");
        assert_eq!(word, "shik");
    }

    #[test]
    fn test_template_with_no_consonants_is_unchanged() {
        let (word, _) = engine(vec![MorphRule::Template("CaCa".into())]).apply_rules("aiu");
        assert_eq!(word, "aiu");
    }

    #[test]
    fn test_reduplication_and_unit_variant_deserialise() {
        let morph: Morphology = toml::from_str("rules = [\"reduplication\"]").unwrap();
        let (word, _) = MorphologyEngine::new(morph).apply_rules("ka");
        assert_eq!(word, "ka-ka");
    }
}
